1038: function CloseSpecialWindows()
1039: 	local found;
1040: 	for index, value in pairs(UISpecialFrames) do
1041: 		local frame = _G[value];
1042: 		if ( frame and frame:IsShown() ) then
1043: 			frame:Hide();
1044: 			found = 1;
1045: 		end
1046: 	end
