205: function HANDLE:GetFrameRef(label)
206: 	if (type(label) ~= "string") then
207: 		return;
208: 	end
209: 	local val = LOCAL_CHECK_Frame.GetAttribute(GetHandleFrame(self), "frameref-" .. label);
210: 	local tv = type(val);
211: 	if (tv == "userdata" and IsFrameHandle(val)) then
212: 		return val;
213: 	end
214: 	return nil;
215: end

702: function SecureHandlerSetFrameRef(frame, label, refFrame)
703: 	if (not IsValidFrame(frame)) then
704: 		error("Invalid frame");
705: 		return;
706: 	end
707: 	if (CheckForbidden(frame)) then
708: 		error("Cannot use SecureHandlers API on forbidden frames");
709: 		return;
710: 	end
711: 	if (type(label) ~= "string") then
712: 		error("Invalid body");
713: 		return;
714: 	end
715: 	if (not IsValidFrame(refFrame)) then
716: 		error("Invalid reference frame");
717: 		return;
718: 	end
719: 	if (CheckForbidden(refFrame)) then
720: 		error("Cannot use SecureHandlers API on forbidden frames");
721: 		return;
722: 	end
723: 	LOCAL_API_Frame:SetAttribute("_apiframe", frame);
724: 	LOCAL_API_Frame:SetAttribute("_frame-" .. label, refFrame);
